exec("#!/usr/bin/env python3\n\"\"\"Bitcoin Paper-Trading Dashboard HTTP Server.\\nSTANDARD LIBRARY ONLY - PAPER MODE ONLY.\\n\"\"\"\\nimport http.server, json, os, urllib.request, threading, time\\n\\nPORT = int(os.environ.get('PORT', 10000))\\ncash = 10.0\\nbtc = 0.0\\ntrades = []\\n\\ndef fetch(url):\\n    try:\\n        with urllib.request.urlopen(url, timeout=8) as r:\\n            return json.loads(r.read().decode())\\n    except Exception:\\n        return None\\n\\nclass H(http.server.BaseHTTPRequestHandler):\\n    def log_message(self, *a): pass\\n    def do_GET(self):\\n        global cash, btc, trades\\n        if self.path == '/health':\\n            d = json.dumps({'status': 'ok'})\\n            self.send_response(200)\\n            self.send_header('Content-Type','application/json')\\n            self.end_headers()\\n            self.wfile.write(d.encode())\\n            return\\n        if self.path == '/api/tick':\\n            try:\\n                t = fetch('https://api.binance.com/api/v3/ticker/price?symbol=BTCUSDT')\\n                kl = fetch('https://api.binance.com/api/v3/klines?symbol=BTCUSDT&interval=1m&limit=25')\\n                if t and kl:\\n                    price = float(t['price'])\\n                    closes = [float(k[4]) for k in kl[:-1]]\\n                    sma5 = sum(closes[-5:])/5 if len(closes)>=5 else 0\\n                    sma20 = sum(closes[-20:])/20 if len(closes)>=20 else 0\\n                    eq = cash + btc * price\\n                    signal = 'BUY' if sma5>sma20 and sma5>0 else 'WAIT'\\n                    d = json.dumps({'price':price,'cash':round(cash,2),'btc':round(btc,6),'equity':round(eq,2),'trades':trades[-5:],'signal':signal})\\n                else:\\n                    d = json.dumps({'error':'fetch failed','price':0,'cash':round(cash,2),'btc':0,'equity':round(cash,2),'signal':'WAIT'})\\n            except Exception:\\n                d = json.dumps({'error':'tick error'})\\n                self.send_response(502)\\n                self.send_header('Content-Type','application/json')\\n                self.end_headers()\\n                self.wfile.write(d.encode())\\n                return\\n            self.send_response(200)\\n            self.send_header('Content-Type','application/json')\\n            self.end_headers()\\n            self.wfile.write(d.encode())\\n            return\\n        self.send_response(200)\\n        self.send_header('Content-Type','text/html')\\n        self.end_headers()\\n        self.wfile.write(b'PAPER MODE ONLY')\\n\\nhttp.server.HTTPServer(('0.0.0.0',PORT),H).serve_forever()")
